<script setup lang="ts">definePageMeta({ layout: 'dashboard', middleware: ['auth'] }); const { data, refresh } = await useFetch<{ data: any[] }>('/api/admin/submissions'); async function remove(id: number) { await $fetch(`/api/admin/submissions/${id}`, { method: 'DELETE' }); await refresh() }</script>
<template><section><h1 class="text-3xl font-semibold">Submissions</h1><div class="mt-8"><EmptyState v-if="!data?.data?.length" title="No submissions yet" /><DataTable v-else :columns="['Name', 'Email', 'Interest', 'Message', 'Actions']"><tr v-for="item in data.data" :key="item.id" class="border-t border-stone-100"><td class="px-5 py-4">{{ item.name }}</td><td class="px-5 py-4">{{ item.email }}</td><td class="px-5 py-4">{{ item.interest }}</td><td class="px-5 py-4">{{ item.message }}</td><td class="px-5 py-4"><button class="text-rose-700" @click="remove(item.id)">Delete</button></td></tr></DataTable></div></section></template>